package dev.ryanhcode.sable.companion.math; public class BoundingBox3d implements BoundingBox3dc { final double a,b,c,d,e,g; public BoundingBox3d(double a,double b,double c,double d,double e,double g){this.a=a;this.b=b;this.c=c;this.d=d;this.e=e;this.g=g;} public double minX(){return a;} public double minY(){return b;} public double minZ(){return c;} public double maxX(){return d;} public double maxY(){return e;} public double maxZ(){return g;} public String toString(){return "box";} }
